public class ContactTriggerHandler {

    public static void handleBefore() {
        Set<Id> accountIds = new Set<Id>();
        for (Contact c : Trigger.new) {
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }

        if (accountIds.isEmpty()) {
            return;
        }

        Map<Id, Account> accountMap = new Map<Id, Account>(
            [SELECT Id, BillingCountry, AccountSource FROM Account WHERE Id IN :accountIds]
        );

        for (Contact c : Trigger.new) {
            if (c.AccountId != null) {
                Account a = accountMap.get(c.AccountId);
                if (a != null) {
                    if (String.isBlank(c.MailingCountry)) {
                        c.MailingCountry = a.BillingCountry;
                    }
                    if (Trigger.isInsert && String.isBlank(c.LeadSource)) {
                        c.LeadSource = a.AccountSource;
                    }
                }
            }
        }
    }

    public static void handleAfterInsert() {
        Set<Id> accountIds = new Set<Id>();
        for (Contact c : Trigger.new) {
            if (c.AccountId != null && String.isNotBlank(c.Phone)) {
                accountIds.add(c.AccountId);
            }
        }

        if (accountIds.isEmpty()) {
            return;
        }

        Map<Id, Account> accountMap = new Map<Id, Account>(
            [SELECT Id, Phone FROM Account WHERE Id IN :accountIds]
        );

        Set<Id> phoneAssigned = new Set<Id>();
        List<Account> accountsToUpdate = new List<Account>();

        for (Contact c : Trigger.new) {
            if (c.AccountId != null && String.isNotBlank(c.Phone)) {
                Account a = accountMap.get(c.AccountId);
                if (a != null && String.isBlank(a.Phone) && !phoneAssigned.contains(c.AccountId)) {
                    a.Phone = c.Phone;
                    phoneAssigned.add(c.AccountId);
                    accountsToUpdate.add(a);
                }
            }
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
