public class ExchangeRateClient {

    public class ExchangeRateException extends Exception {}

    private static final String ENDPOINT = 'callout:FB_Exchange_Rates/v1/latest';

    public static Map<String, Decimal> getRates(String baseCurrency, Set<String> quoteCurrencies) {
        // --- Validate & normalise (no callout if invalid) ---
        if (quoteCurrencies == null || quoteCurrencies.isEmpty()) {
            throw new ExchangeRateException('quoteCurrencies must not be null or empty');
        }

        String normalisedBase = validateAndNormalise(baseCurrency);

        List<String> normalisedQuotes = new List<String>();
        for (String q : quoteCurrencies) {
            normalisedQuotes.add(validateAndNormalise(q));
        }

        // --- Build request ---
        String symbols = String.join(',', normalisedQuotes);
        String url = ENDPOINT
                   + '?base=' + EncodingUtil.urlEncode(normalisedBase, 'UTF-8')
                   + '&symbols=' + symbols;

        // --- First attempt ---
        HttpResponse res = doRequest(url);

        // --- Retry once on 503 ---
        if (res.getStatusCode() == 503) {
            res = doRequest(url);
        }

        // --- Check final status ---
        if (res.getStatusCode() != 200) {
            throw new ExchangeRateException(
                'Unexpected HTTP status code: ' + res.getStatusCode()
            );
        }

        // --- Parse response body ---
        Map<String, Object> body;
        try {
            body = (Map<String, Object>) JSON.deserializeUntyped(res.getBody());
        } catch (Exception e) {
            throw new ExchangeRateException('Unable to parse response body: ' + e.getMessage());
        }

        Object ratesObj = body.get('rates');
        if (ratesObj == null) {
            throw new ExchangeRateException('Response body is missing the "rates" object');
        }

        Map<String, Object> rates = (Map<String, Object>) ratesObj;

        // --- Build result map (ignore extra rates in response) ---
        Map<String, Decimal> result = new Map<String, Decimal>();
        for (String code : normalisedQuotes) {
            if (!rates.containsKey(code)) {
                throw new ExchangeRateException('No rate available for currency: ' + code);
            }
            try {
                result.put(code, (Decimal) rates.get(code));
            } catch (Exception e) {
                throw new ExchangeRateException('Invalid rate value for currency: ' + code);
            }
        }

        return result;
    }

    // ------------------------------------------------------------------ private

    private static HttpResponse doRequest(String url) {
        HttpRequest req = new HttpRequest();
        req.setEndpoint(url);
        req.setMethod('GET');
        req.setHeader('Accept', 'application/json');
        Http http = new Http();
        return http.send(req);
    }

    private static String validateAndNormalise(String code) {
        if (code == null) {
            throw new ExchangeRateException('Currency code must not be null');
        }
        String normalised = code.trim().toUpperCase();
        if (normalised.length() != 3 || !Pattern.matches('[A-Z]{3}', normalised)) {
            throw new ExchangeRateException('Invalid currency code: "' + code + '"');
        }
        return normalised;
    }
}
