public with sharing class ContactDomainService {
    public static Map<String, List<Contact>> groupByEmailDomain(Set<Id> accountIds) {
        Map<String, List<Contact>> contactsByEmailDomain = new Map<String, List<Contact>>();

        if (accountIds == null || accountIds.isEmpty()) {
            return contactsByEmailDomain;
        }

        Set<Id> accountIdsToQuery = new Set<Id>();
        for (Id accountId : accountIds) {
            if (accountId != null) {
                accountIdsToQuery.add(accountId);
            }
        }

        if (accountIdsToQuery.isEmpty()) {
            return contactsByEmailDomain;
        }

        List<Contact> contacts = [
            SELECT Id, Email, AccountId
            FROM Contact
            WHERE AccountId IN :accountIdsToQuery
            WITH USER_MODE
        ];

        for (Contact c : contacts) {
            if (c.Email == null || String.isBlank(c.Email) || c.AccountId == null) {
                continue;
            }

            Integer atIndex = c.Email.lastIndexOf('@');
            if (atIndex <= 0 || atIndex == c.Email.length() - 1) {
                continue;
            }

            String emailDomain = c.Email.substring(atIndex + 1).trim().toLowerCase();
            if (String.isBlank(emailDomain)) {
                continue;
            }

            if (!contactsByEmailDomain.containsKey(emailDomain)) {
                contactsByEmailDomain.put(emailDomain, new List<Contact>());
            }

            contactsByEmailDomain.get(emailDomain).add(c);
        }

        return contactsByEmailDomain;
    }
}
