public class ContactLookupAction {

    @InvocableMethod(
        label='Find Contact by Email'
        description='Locates an existing Contact by email address, returning the one with the earliest CreatedDate on duplicates.'
        category='Contact'
    )
    public static List<Result> find(List<Request> requests) {

        // 1. Collect the unique, trimmed, non-blank emails
        Set<String> emailSet = new Set<String>();
        for (Request req : requests) {
            if (req.email != null && String.isNotBlank(req.email)) {
                emailSet.add(req.email.trim());
            }
        }

        // 2. One SOQL query (bulk-safe, max 50 000 rows); respect running-user sharing
        Map<String, Id> emailToContactId = new Map<String, Id>();
        if (!emailSet.isEmpty()) {
            for (Contact c : [
                SELECT Id, Email
                FROM Contact
                WHERE Email IN :emailSet
                WITH SHARED
                ORDER BY CreatedDate ASC
                LIMIT 50000
            ]) {
                String key = c.Email.toLowerCase();
                // First row per email wins because of ORDER BY CreatedDate ASC
                if (!emailToContactId.containsKey(key)) {
                    emailToContactId.put(key, c.Id);
                }
            }
        }

        // 3. Build one Result per Request, in order
        List<Result> results = new List<Result>(requests.size());
        for (Request req : requests) {
            Result r = new Result();
            if (req.email != null && String.isNotBlank(req.email)) {
                String key = req.email.trim().toLowerCase();
                Id matched = emailToContactId.get(key);
                r.contactId = matched;
                r.found     = matched != null;
            } else {
                r.contactId = null;
                r.found     = false;
            }
            results.add(r);
        }
        return results;
    }

    // ── Input ──────────────────────────────────────────────────────────
    public class Request {
        @InvocableVariable(required=true  description='Email address to look up')
        public String email;
    }

    // ── Output ─────────────────────────────────────────────────────────
    public class Result {
        @InvocableVariable(description='Id of the matching Contact, or null when not found')
        public Id contactId;

        @InvocableVariable(description='True when a Contact was found for the given email')
        public Boolean found;
    }
}
