/**
 * Recalculates FB_Open_Pipeline__c (sum of open opp Amounts) and
 * FB_Open_Opportunities__c (count of open opps) on every affected Account.
 *
 * Recursion guard prevents infinite loops when AccountTrigger fires
 * (AccountTrigger updates open opportunities' Rating, which re-triggers this
 * handler).
 */
public class OpportunityPipelineHandler {

    // Recursion guard: prevents re-entry when AccountTrigger cascades back.
    private static Boolean isRunning = false;

    /**
     * Single entry point invoked from the trigger for every supported event.
     */
    public static void handle() {
        if (isRunning) {
            return;
        }

        try {
            isRunning = true;

            Set<Id> affectedAccountIds = getAffectedAccountIds();
            if (affectedAccountIds.isEmpty()) {
                return;
            }

            recalculateAccounts(affectedAccountIds);
        } finally {
            isRunning = false;
        }
    }

    // ------------------------------------------------------------------
    // Determine which Account Ids are relevant for this DML event.
    // ------------------------------------------------------------------
    private static Set<Id> getAffectedAccountIds() {
        Set<Id> ids = new Set<Id>();

        if (Trigger.isInsert) {
            for (Opportunity o : Trigger.new) {
                if (o.AccountId != null) {
                    ids.add(o.AccountId);
                }
            }
        } else if (Trigger.isUpdate) {
            // New account (current) and old account (for re-parenting)
            for (Opportunity o : Trigger.new) {
                if (o.AccountId != null) {
                    ids.add(o.AccountId);
                }
            }
            for (Opportunity o : Trigger.old) {
                if (o.AccountId != null) {
                    ids.add(o.AccountId);
                }
            }
        } else if (Trigger.isDelete) {
            for (Opportunity o : Trigger.old) {
                if (o.AccountId != null) {
                    ids.add(o.AccountId);
                }
            }
        } else if (Trigger.isUndelete) {
            for (Opportunity o : Trigger.new) {
                if (o.AccountId != null) {
                    ids.add(o.AccountId);
                }
            }
        }

        return ids;
    }

    // ------------------------------------------------------------------
    // Query the database for the true current state of every affected
    // Account's pipeline, then write the correct values back.
    // Batching (100 per query) stays well under the 200-group aggregate
    // query default limit, making this safe for 200+ records.
    // ------------------------------------------------------------------
    private static void recalculateAccounts(Set<Id> accountIds) {
        // Seed every affected account with 0 / 0 so accounts that end up
        // with no open opps show zeros rather than blank/null.
        Map<Id, Decimal> amountByAccount = new Map<Id, Decimal>();
        Map<Id, Integer> countByAccount = new Map<Id, Integer>();
        for (Id accId : accountIds) {
            amountByAccount.put(accId, Decimal.valueOf(0));
            countByAccount.put(accId, 0);
        }

        // Batch the aggregate query to stay under the 200-group ceiling.
        List<Id> idList = new List<Id>(accountIds);
        for (Integer i = 0; i < idList.size(); i += 100) {
            Integer end = Math.min(i + 100, idList.size());
            List<Id> batch = idList.subList(i, end);

            for (AggregateResult ar : [
                SELECT AccountId,
                       SUM(Amount) totalAmount,
                       COUNT(Id)   totalCount
                FROM Opportunity
                WHERE AccountId IN :batch
                  AND IsClosed = false
                GROUP BY AccountId
            ]) {
                Id accId = (Id)ar.get('AccountId');
                Decimal amt = (Decimal)ar.get('totalAmount');
                Integer cnt = (Integer)ar.get('totalCount');

                amountByAccount.put(accId, amt != null ? amt : Decimal.valueOf(0));
                countByAccount.put(accId, cnt != null ? cnt : 0);
            }
        }

        // Write the recalculated values.  Always update every affected
        // account so the totals are deterministic after each DML statement.
        List<Account> toUpdate = new List<Account>();
        for (Id accId : accountIds) {
            toUpdate.add(new Account(
