        return System.schedule('Log purge (nightly)', '0 0 2 * * ?', new LogPurgeJob());
    }

    // ── Schedulable ──────────────────────────────────────────────────
    public void execute(SchedulableContext sc) {
        Database.executeBatch(new LogPurgeJob(), 200);
    }

    // ── Database.Batchable ───────────────────────────────────────────
    public Database.QueryLocator start(Database.BatchableContext bc) {
        Datetime thirtyDaysAgo   = Datetime.now().addDays(-30);
        Datetime oneEightyDaysAgo = Datetime.now().addDays(-180);

        // Delete non-ERROR records older than 30 days;
        // delete ERROR records only when older than 180 days.
        return Database.getQueryLocator([
            SELECT Id
            FROM   FB_Integration_Log__c
            WHERE  (Level__c != 'ERROR' AND CreatedDate < :thirtyDaysAgo)
               OR  (Level__c  = 'ERROR' AND CreatedDate < :oneEightyDaysAgo)
        ]);
    }

    public void execute(Database.BatchableContext bc, List<FB_Integration_Log__c> scope) {
        Database.DeleteResult[] results = Database.delete(scope, false);
        for (Database.DeleteResult res : results) {
            if (!res.isSuccess()) {
                // Log failures without throwing (keeps the batch running)
                // In production you could write to a dedicated error log.
            }
        }
    }

    public void finish(Database.BatchableContext bc) {
        // Intentionally left empty.
    }
}
