public with sharing class OpportunityRollupService {

    public static Map<Id, Decimal> wonAmountThisYear(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return new Map<Id, Decimal>();
        }

        // Seed every requested account with 0 so the map is complete up front.
        Map<Id, Decimal> result = new Map<Id, Decimal>();
        for (Id acctId : accountIds) {
            result.put(acctId, Decimal.valueOf(0));
        }

        // Calendar-year boundaries for the running user's today.
        Integer yr = Date.today().year();
        Date yearStart = Date.newInstance(yr, 1, 1);
        Date yearEnd   = Date.newInstance(yr, 12, 31);

        // Single aggregate SOQL – never loads individual Opportunity records.
        for (AggregateResult ar : [
            SELECT AccountId, SUM(Amount) totalAmount
            FROM   Opportunity
            WHERE  IsWon      = true
              AND  CloseDate >= :yearStart
              AND  CloseDate <= :yearEnd
              AND  AccountId IN :accountIds
            GROUP BY AccountId
        ]) {
            Id    acctId  = (Id)    ar.get('AccountId');
            Decimal total = (Decimal) ar.get('totalAmount');

            // total is null when every matching Amount is blank → leave the entry at 0.
            if (acctId != null && total != null) {
                result.put(acctId, total);
            }
        }

        return result;
    }
}
