public class Opportunities extends fflib_SObjectDomain {

    public Opportunities(List<Opportunity> records) {
        super(records);
    }

    public class Constructor implements fflib_SObjectDomain.IConstructable {
        public fflib_SObjectDomain construct(List<SObject> sObjectList) {
            return new Opportunities(sObjectList);
        }
    }

    @Override
    public void onBeforeInsert() {
        validateAmount((List<Opportunity>) records, null);
    }

    @Override
    public void onBeforeUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        validateAmount((List<Opportunity>) triggerNew, (List<Opportunity>) triggerOld);
    }

    private void validateAmount(List<Opportunity> triggerNew, List<Opportunity> triggerOld) {
        for (Integer i = 0; i < triggerNew.size(); i++) {
            Opportunity opp = triggerNew[i];

            // Rule 1: Amount must not be negative (insert & update)
            if (opp.Amount != null && opp.Amount < 0) {
                error('Amount cannot be negative.', opp, Opportunity.Amount);
            }

            // Rule 2: On update, if stage was already Closed Won before this update,
            //         Amount cannot change.
            if (triggerOld != null) {
                Opportunity oldOpp = triggerOld[i];
                if (oldOpp.StageName == 'Closed Won' && opp.Amount != oldOpp.Amount) {
                    error('Amount cannot change on a won opportunity.', opp, Opportunity.Amount);
                }
            }
        }
    }
}
