public inherited sharing class AccountsSelector extends fflib_SObjectSelector {

    /**
     * Constructor used by the Application selector factory:
     *   Application.Accounts = AccountsSelector::new
     *
     * The selector's data-access setting is configured here so that every
     * query the selector generates appends WITH USER_MODE, causing the
     * platform to enforce the running user's object-level, field-level
     * and record-level (sharing) security at SOQL time.
     */
    public AccountsSelector() {
        // Set the selector-level data-access mode to user mode.
        // fflib_SObjectSelector propagates this setting into every SOQL
        // string it builds (newQueryLocator / selectSObjectsById).
        this.setDataAccess(fflib_SObjectSelector.DataAccess.UserMode);
    }

    // ─────────────────────────────────────────────────────────────
    // fflib_SObjectSelector required overrides
    // ─────────────────────────────────────────────────────────────

    @Override
    public Schema.SObjectType getSObjectType() {
        return Account.SObjectType;
    }

    /**
     * Fields selected by default in every query:
     *   Id, Name, Industry  +  whatever is in the Credit_Review field set.
     *
     * The field-set members are read from metadata at runtime so that
     * administrators can add/remove fields (today AnnualRevenue, Rating)
     * without a code deployment.
     */
    @Override
    public List<Schema.SObjectField> getSObjectFieldList() {
        List<Schema.SObjectField> fields = new List<Schema.SObjectField>{
            Account.Id,
            Account.Name,
            Account.Industry
        };

        Map<String, Schema.FieldSet> fieldSets =
            Account.SObjectType.getDescribe().getFieldSets();
        Schema.FieldSet creditReview = fieldSets.get('Credit_Review');
        if (creditReview != null) {
            for (Schema.FieldSetMember member : creditReview.getDisplayedFields()) {
                fields.add(member.getField());
            }
        }
        return fields;
    }

    // ─────────────────────────────────────────────────────────────
    // Public query methods
    // ─────────────────────────────────────────────────────────────

    /**
     * Returns accounts by Id, selecting all fields from getSObjectFieldList()
     * (Id, Name, Industry + Credit_Review members) in user mode.
     */
    public List<Account> selectById(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return new List<Account>();
        }
        return (List<Account>) selectSObjectsById(accountIds);
    }

    /**
     * Returns accounts (with the same field set) together with their
     * child Contacts in a single SOQL relationship query.
     *
     * The contact subquery fields are sourced from ContactsSelector so
     * that any change in the contacts selector propagates here without
     * code duplication.  Runs in user mode (WITH USER_MODE).
     */
    public List<Account> selectByIdWithContacts(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return new List<Account>();
        }

        ContactsSelector contactsSelector = new ContactsSelector();

        String accountFields = fieldsToString(getSObjectFieldList());
        String contactFields = fieldsToString(contactsSelector.getSObjectFieldList());

        // Build SOQL: account fields + contacts subquery + user-mode enforcement
        String soql = 'SELECT ' + accountFields
            + ', (SELECT ' + contactFields + ' FROM Contacts) '
            + 'FROM Account '
            + 'WHERE Id IN :accountIds '
            + 'WITH USER_MODE';

        return Database.query(soql);
    }

    // ─────────────────────────────────────────────────────────────
    // Private helpers
    // ─────────────────────────────────────────────────────────────

    /**
     * Converts a list of field tokens to a comma-separated SOQL field list.
     * Uses each field's describe to resolve the API name, which keeps the
     * method agnostic of whether the field came from the hard-coded list
     * or from a field set.
     */
    private String fieldsToString(List<Schema.SObjectField> fields) {
        List<String> names = new List<String>();
        for (Schema.SObjectField field : fields) {
            names.add(field.getDescribe().getFieldName());
        }
        return String.join(',', names);
    }
}
