public class CaseEscalationService {

    public static class EscalationException extends Exception {
        public EscalationException() {
            super();
        }

        public EscalationException(String message) {
            super(message);
        }
    }

    public static void escalate(Set<Id> caseIds, String reason) {
        if (String.isBlank(reason)) {
            throw new EscalationException('Escalation reason is required.');
        }

        if (caseIds == null || caseIds.isEmpty()) {
            return;
        }

        List<Case> cases = CasesSelector.newInstance().selectById(caseIds);
        if (cases == null || cases.isEmpty()) {
            return;
        }

        fflib_ISObjectUnitOfWork uow = Application.UnitOfWork.newInstance();
        boolean hasEscalations = false;
        Date tomorrow = Date.today().addDays(1);

        for (Case currentCase : cases) {
            if (currentCase.Status == 'Closed' || (currentCase.IsEscalated != null && currentCase.IsEscalated)) {
                continue;
            }

            currentCase.IsEscalated = true;
            currentCase.Priority = 'High';
            uow.registerDirty(currentCase);

            uow.registerNew(new Task(
                WhatId = currentCase.Id,
                OwnerId = currentCase.OwnerId,
                Subject = 'Escalated: ' + reason,
                ActivityDate = tomorrow,
                Priority = 'High'
            ));

            hasEscalations = true;
        }

        if (hasEscalations) {
            uow.commitWork();
        }
    }
}
