public with sharing class ContactPhoneCleanup {
    /**
     * Normalizes Contact.Phone so it contains only digits and plus signs,
     * then updates all phone-bearing contacts in a single bulk DML call.
     *
     * Returns the Id of each contact that failed to save to its first error message.
     */
    public static Map<Id, String> normalizePhones(List<Id> contactIds) {
        Map<Id, String> saveFailures = new Map<Id, String>();

        if (contactIds == null || contactIds.isEmpty()) {
            return saveFailures;
        }

        Set<Id> contactIdSet = new Set<Id>();
        for (Id contactId : contactIds) {
            if (contactId != null) {
                contactIdSet.add(contactId);
            }
        }

        if (contactIdSet.isEmpty()) {
            return saveFailures;
        }

        List<Contact> contacts = new List<Contact>();

        for (Contact contact : [SELECT Id, Phone FROM Contact WHERE Id IN :contactIdSet]) {
            if (!String.isNotBlank(contact.Phone)) {
                continue;
            }

            // Keep only digits and plus signs.
            contact.Phone = contact.Phone.replaceAll('[^+\\d]', '');
            contacts.add(contact);
        }

        if (contacts.isEmpty()) {
            return saveFailures;
        }

        Database.SaveResult[] saveResults = Database.update(contacts, false);

        for (Integer i = 0; i < saveResults.size(); i++) {
            if (!saveResults[i].isSuccess()) {
                Database.Error[] errors = saveResults[i].getErrors();
                String message = (errors == null || errors.isEmpty())
                    ? ''
                    : errors[0].getMessage();

                saveFailures.put(contacts[i].Id, (message == null) ? '' : message);
            }
        }

        return saveFailures;
    }
}
