/**
 * PipelineSummary provides stage-level totals for the open pipeline stages used
 * by sales operations.
 *
 * Implementation choice:
 * I would use one aggregate query grouped by StageName rather than one query
 * per stage. The stage set is fixed and small, so both approaches are correct,
 * but the grouped query avoids SOQL inside a loop, uses fewer round trips, and
 * remains easy to read.
 */
public with sharing class PipelineSummary {
    private static final List<String> MANAGED_STAGES = new List<String>{
        'Prospecting',
        'Qualification',
        'Proposal/Price Quote',
        'Negotiation/Review'
    };

    public static Map<String, Decimal> totalsByStage(Date fromDate, Date toDate) {
        Map<String, Decimal> totals = new Map<String, Decimal>();

        for (String stage : MANAGED_STAGES) {
            totals.put(stage, Decimal.valueOf(0));
        }

        if (fromDate == null || toDate == null || fromDate > toDate) {
            return totals;
        }

        List<AggregateResult> results = [
            SELECT StageName, SUM(Amount) sumAmount
            FROM Opportunity
            WHERE StageName IN :MANAGED_STAGES
              AND CloseDate BETWEEN :fromDate AND :toDate
            GROUP BY StageName
        ];

        for (AggregateResult result : results) {
