```apex
/**
 * ErpCustomerSync
 *
 * Implements Queueable so the ERP POST can run in a fresh transaction
 * (synchronous callouts are not allowed after DML).  One HTTP request
 * per Account so the ERP team can trace each customer individually.
 *
 * Endpoint : POST callout:ERP/api/customers
 * Body     : [{"salesforceId":"001…","name":"…","country":"…"}]
 * Response : 202 Accepted  (error handling / retries out of scope)
 *
 * Async callout ceiling per execution is 100; the class chains itself
 * when the pending list exceeds that limit.
 */
public with sharing class ErpCustomerSync implements Queueable {

    /* ------------------------------------------------------------------ */
    //  Constants
    /* ------------------------------------------------------------------ */
    private static final String   ENDPOINT          = 'callout:ERP/api/customers';
    private static final Integer  MAX_CALLOUTS      = 100;   // async cap per execution

    /* ------------------------------------------------------------------ */
    //  Instance state
    /* ------------------------------------------------------------------ */
    private final List<Account> accounts;
    private final Integer       nextIndex;

    /* ------------------------------------------------------------------ */
    //  Public API – entry point called from the trigger
    /* ------------------------------------------------------------------ */

    /**
     * Enqueue a single async job that will POST one HTTP request per
     * Account.  Passes only IDs + minimal field data so the Queueable
     * serialization stays small.
     */
    public static void enqueue(List<Account> newAccounts) {
        if (newAccounts == null || newAccounts.isEmpty()) {
            return;
        }

        // Build lightweight DTO list to keep the Queueable payload small.
        List<AccountDto> dtos = new List<AccountDto>();
        for (Account acc : newAccounts) {
            dtos.add(new AccountDto(
                (Id) acc.Id,
                acc.Name,
                acc.BillingCountry
            ));
        }
        System.enqueueJob(new ErpCustomerSync(dtos, 0));
    }

    /* ------------------------------------------------------------------ */
    //  Constructor(s)
    /* ------------------------------------------------------------------ */
    public ErpCustomerSync(List<AccountDto> accounts) {
        this(accounts, 0);
    }

    /** Chain constructor – resumes at {@code nextIndex}. */
    public ErpCustomerSync(List<AccountDto> accounts, Integer nextIndex) {
        this.accounts  = accounts;
        this.nextIndex = nextIndex;
    }

    /* ------------------------------------------------------------------ */
    //  Queueable contract
    /* ------------------------------------------------------------------ */
    public void execute(QueueableContext context) {
        if (accounts == null) return;

        Integer end = Math.min(nextIndex + MAX_CALLOUTS, accounts.size());

        for (Integer i = nextIndex; i < end; i++) {
            AccountDto dto = accounts[i];
            HTTP request   = buildRequest(dto);

            HTTPResponse response = new HTTP().send(request);

            // 202 Accepted expected; error handling / retries are out of scope.
            // Log a warning if the ERP returned something unexpected so the
            // integration is still observable.
            if (response.getStatusCode() < 200 || response.getStatusCode() >= 300) {
                System.debug(Log.LoggingLevel.WARN,
                    'ErpCustomerSync – unexpected status ' + response.getStatusCode()
                    + ' for Account ' + dto.sfId);
            }
        }

        // Chain if more accounts remain.
        if (end < accounts.size()) {
            System.enqueueJob(new ErpCustomerSync(accounts, end));
        }
    }

    /* ------------------------------------------------------------------ */
    //  Private helpers
    /* ------------------------------------------------------------------ */
    private static HTTP buildRequest(AccountDto dto) {
        // One-element JSON array so the ERP body contract is satisfied.
        List<Map<String, Object>> payload = new List<Map<String, Object>>{
            new Map<String, Object>{
                'salesforceId' => dto.sfId,
                'name'         => dto.name,
                'country'      => dto.country          // null serialises as null
            }
        };

        HTTP req = new HTTP();
        req.setMethod('POST');
        req.setEndpoint(ENDPOINT);
        req.setHeader('Content-Type', 'application/json');
        req.setBody(JSON.serialize(payload));
        return req;
    }

    /* ------------------------------------------------------------------ */
    //  Inner DTO – avoids serialising full sObjects into the Queueable
    //  payload while remaining Serializable across transactions.
    /* ------------------------------------------------------------------ */
    public class AccountDto implements Serializable {
        public Id      sfId;
        public String  name;
        public String  country;

        public AccountDto(Id sfId, String name, String country) {
            this.sfId   = sfId;
            this.name   = name;
            this.country = country;
        }
    }
}
```

