public with sharing class LeadContactMatcher {
    /**
     * Returns a contact Id for each lead by email, matching the order and size of `leads`.
     */
    public static List<Id> matchByEmail(List<Lead> leads, List<Contact> contacts) {
        List<Id> matchedContactIds = new List<Id>();

        if (leads == null) {
            return matchedContactIds;
        }

        // First-occurrence email map:
        // - preserves the first matching contact order
        // - avoids comparing every lead against every contact
        Map<String, Id> contactIdByNormalizedEmail = new Map<String, Id>();

        if (contacts != null) {
            for (Contact contact : contacts) {
                if (contact == null || contact.Id == null) {
                    continue;
                }

                String normalizedContactEmail = normalizeEmail(contact.Email);
                if (normalizedContactEmail != null && !contactIdByNormalizedEmail.containsKey(normalizedContactEmail)) {
                    contactIdByNormalizedEmail.put(normalizedContactEmail, contact.Id);
                }
            }
        }

        for (Lead lead : leads) {
            String normalizedLeadEmail = (lead == null) ? null : normalizeEmail(lead.Email);

            if (normalizedLeadEmail == null) {
                matchedContactIds.add(null);
            } else {
                matchedContactIds.add(contactIdByNormalizedEmail.get(normalizedLeadEmail));
            }
        }

        return matchedContactIds;
    }

    private static String normalizeEmail(String email) {
        if (email == null) {
            return null;
        }

        String normalized = email.trim();
        return normalized.length() == 0 ? null : normalized.toLowerCase();
    }
}
