/**
 * Handler for Account after-update trigger.
 *
 * When an Account's BillingCountry changes, synchronise MailingCountry
 * on child Contacts that are "in sync" with the account (blank or equal
 * to the previous BillingCountry).  Contacts whose MailingCountry differs
 * from the old value are left untouched (they work abroad).
 *
 * Bulk-safe: one selective SOQL (indexed on AccountId), one DML.
 */
public class AccountCountrySync {

    public static void handleAfterUpdate(List<Account> newRecords, Map<Id, Account> oldMap) {
        // --- 1. Identify accounts whose BillingCountry actually changed ----------
        Map<Id, String> newCountryById = new Map<Id, String>();
        Map<Id, String> oldCountryById = new Map<Id, String>();

        for (Account newAcc : newRecords) {
            Account oldAcc = oldMap.get(newAcc.Id);
            if (oldAcc != null && oldAcc.BillingCountry != newAcc.BillingCountry) {
                newCountryById.put(newAcc.Id, newAcc.BillingCountry);
                oldCountryById.put(newAcc.Id, oldAcc.BillingCountry);
            }
        }

        if (newCountryById.isEmpty()) {
            return; // nothing to do
        }

        // --- 2. Single selective query – AccountId is indexed -------------------
        List<Contact> contactsToUpdate = new List<Contact>();

        for (Contact c : [
            SELECT Id, AccountId, MailingCountry
              FROM Contact
             WHERE AccountId IN :newCountryById.keySet()
        ]) {
            String oldCountry = oldCountryById.get(c.AccountId);

            // Update only when MailingCountry is blank or still equals the old country
            if (String.isBlank(c.MailingCountry) || c.MailingCountry == oldCountry) {
                c.MailingCountry = newCountryById.get(c.AccountId);
                contactsToUpdate.add(c);
            }
        }

        // --- 3. Batch DML (skip when nothing changed to avoid empty DML) --------
        if (!contactsToUpdate.isEmpty()) {
            update contactsToUpdate;
        }
    }
}
```

