import { LightningElement, api, wire } from 'lwc';
import { getRecord } from 'lightning/uiRecordApi';

const ACCOUNT_FIELDS = [
    'Account.Name',
    'Account.Industry',
    'Account.AnnualRevenue',
    'Account.Owner.Name'
];

export default class AccountHeader extends LightningElement {
    @api recordId;

    @wire(getRecord, { recordId: '$recordId', fields: ACCOUNT_FIELDS })
    accountWire;

    get data() {
        return this.accountWire ? this.accountWire.data : undefined;
    }

    get error() {
        return this.accountWire ? this.accountWire.error : undefined;
    }

    get isLoading() {
        return !this.data && !this.error;
    }

    get name() {
        return this.data ? this.data.Name : undefined;
    }

    get industry() {
        return this.data ? this.data.Industry : undefined;
    }

    get revenue() {
        return this.data ? this.data.AnnualRevenue : undefined;
    }

    get ownerName() {
        return (this.data && this.data.Owner) ? this.data.Owner.Name : undefined;
    }
}
