import { LightningElement, api, track } from 'lwc';
import { NavigationMixin } from 'lightning/navigation';
import { encodeDefaultFieldValues } from 'lightning/pageReferenceUtils';

export default class AccountQuickLinks extends NavigationMixin(LightningElement) {
    @api recordId;

    @track caseUrl = '';

    isDisconnected = false;

    connectedCallback() {
        this.generateCaseListUrl();
    }

    disconnectedCallback() {
        this.isDisconnected = true;
    }

    handleAction(event) {
        const action = event.currentTarget.dataset.action;

        if (!action || !this.recordId) {
            return;
        }

        switch (action) {
            case 'new-contact':
                this[NavigationMixin.Navigate]({
                    type: 'standard__objectPage',
                    attributes: {
                        objectApiName: 'Contact',
                        actionName: 'new'
                    },
                    state: {
                        defaultFieldValues: encodeDefaultFieldValues({
                            AccountId: this.recordId
                        })
                    }
                });
                break;

            case 'contacts':
                this[NavigationMixin.Navigate]({
                    type: 'standard__relatedList',
                    attributes: {
                        objectApiName: 'Account',
                        relationshipName: 'Contacts',
                        actionName: 'view',
                        recordId: this.recordId
                    }
                });
                break;

            case 'edit':
                this[NavigationMixin.Navigate]({
                    type: 'standard__recordPage',
                    attributes: {
                        objectApiName: 'Account',
                        recordId: this.recordId,
                        actionName: 'edit'
                    }
                });
                break;

            default:
                break;
        }
    }

    generateCaseListUrl() {
        this[NavigationMixin.GenerateUrl]({
            type: 'standard__objectPage',
            attributes: {
                objectApiName: 'Case',
                actionName: 'list'
            },
            state: {
                filterName: 'My_Open_Cases'
            }
        })
            .then((url) => {
                if (!this.isDisconnected) {
                    this.caseUrl = url;
                }
            })
            .catch(() => {
                // If URL generation fails, leave the cases link hidden.
            });
    }
}
