import { LightningElement } from 'lwc';
import { ShowToastEvent } from 'lightning/platformShowToastEvent';
import register from '@salesforce/apex/RegistrationController.register';

const FREE_EMAIL_DOMAINS = ['gmail.com', 'yahoo.com', 'hotmail.com', 'outlook.com'];

export default class EventRegistrationForm extends LightningElement {
    values = {
        fullName: '',
        email: '',
        company: ''
    };

    handleChange(event) {
        const field = event.currentTarget?.dataset?.field;
        const value = event.detail?.value ?? '';

        if (field) {
            this.values[field] = value;
        }
    }

    async handleRegister() {
        const fullName = this.values.fullName || '';
        const email = (this.values.email || '').trim();
        const company = this.values.company || '';

        const emailInput = this.template.querySelector('lightning-input[data-field="email"]');
        if (emailInput) {
            const domain = email.includes('@') ? email.split('@').pop().trim().toLowerCase() : '';

            if (FREE_EMAIL_DOMAINS.includes(domain)) {
                emailInput.setCustomValidity('Use your work email address.');
            } else {
                emailInput.setCustomValidity('');
            }
        }

        const inputs = Array.from(this.template.querySelectorAll('lightning-input[data-field]'));
        const results = await Promise.all(inputs.map((input) => Promise.resolve(input.reportValidity())));
        const isValid = results.every((valid) => valid !== false);

        if (!isValid) {
            return;
        }

        try {
            await register({ fullName, email, company });
            this.dispatchEvent(
                new ShowToastEvent({
                    variant: 'success',
                    title: 'Registered'
                })
            );
        } catch (error) {
            this.dispatchEvent(
                new ShowToastEvent({
                    variant: 'error',
                    title: 'Registration failed',
                    message: error?.body?.message || error?.message || 'Registration failed'
                })
            );
        }
    }
}
