import { LightningElement, api } from 'lwc';

export default class TaskChecklist extends LightningElement {
    _heading = '';
    items = [];
    newLabel = '';
    nextId = 1;

    @api
    get heading() {
        return this._heading ? this._heading.toUpperCase() : '';
    }

    set heading(value) {
        this._heading = value != null ? String(value) : '';
    }

    @api
    get tasks() {
        return this.items.map((task) => ({ ...task }));
    }

    set tasks(value) {
        if (Array.isArray(value)) {
            this.items = value.map((task) => ({ ...task }));
        } else {
            this.items = [];
        }
    }

    get remaining() {
        return this.items.filter((task) => !task.done).length;
    }

    handleLabelChange(event) {
        this.newLabel = event.detail.value;
    }

    handleAdd() {
        const trimmed = this.newLabel ? this.newLabel.trim() : '';
        if (!trimmed) {
            return;
        }
        const newItem = { id: `new-${this.nextId++}`, label: trimmed, done: false };
        this.items = [...this.items, newItem];
        this.newLabel = '';
        this.dispatchEvent(
            new CustomEvent('taskadded', {
                detail: { label: trimmed },
                bubbles: true,
                composed: true
            })
        );
    }

    handleToggle(event) {
        const id = event.target.dataset.id;
        if (!id) {
            return;
        }
        this.items = this.items.map((task) =>
            task.id === id ? { ...task, done: !task.done } : task
        );
    }
}
