/**
 * EmployerService – manages current-employer affiliations on NPSP contacts.
 *
 * Uses NPSP's standard Affiliation automation:
 *   • Inserting a new Primary + Current Affiliation causes NPSP to automatically
 *     end the prior primary affiliation (Former, EndDate = today).
 *   • The Contact.npsp__Primary_Affiliation__c lookup is explicitly set to the
 *     target Organization so the requirement holds regardless of flow/trigger config.
 *
 * Limits honoured:
 *   • 1 SOQL query (existing affiliations for the given contacts)
 *   • 2 DML statements max (insert affiliations + update contact lookups)
 *   • Handles 200 contacts in a single bulk call
 */
public with sharing class EmployerService {

    public static void setCurrentEmployers(Map<Id, Id> employerByContactId) {

        // Guard: null or empty map – nothing to do
        if (employerByContactId == null || employerByContactId.isEmpty()) {
            return;
        }

        Set<Id> contactIds = new Set<Id>(employerByContactId.keySet());

        // ── SOQL 1 ──────────────────────────────────────────────────────────
        // Identify contacts whose CURRENT, PRIMARY affiliation already points
        // to the target Organization – those need no change (avoids duplicates).
        Set<Id> alreadyCurrent = new Set<Id>();
        for (npe5__Affiliation__c aff : [
            SELECT npe5__Contact__c, npe5__Organization__c
            FROM   npe5__Affiliation__c
            WHERE  npe5__Contact__c   IN :contactIds
              AND  npe5__Status__c    = 'Current'
              AND  npe5__Primary__c   = true
        ]) {
            Id ctId = (Id)aff.npe5__Contact__c;
            Id orgId = employerByContactId.get(ctId);
            if (orgId != null && aff.npe5__Organization__c == orgId) {
                alreadyCurrent.add(ctId);
            }
        }

        // ── Build records ────────────────────────────────────────────────────
        Date    today          = Date.today();
        List<npe5__Affiliation__c> newAffiliations   = new List<npe5__Affiliation__c>();
        List<Contact>             contactsToUpdate  = new List<Contact>();

        for (Id ctId : contactIds) {
            if (alreadyCurrent.contains(ctId)) {
                continue; // Already Current + Primary with the target org
            }

            Id orgId = employerByContactId.get(ctId);
            if (orgId == null) {
                continue; // Skip entries without a valid Organization
            }

            // New Current, Primary affiliation (NPSP ends the old primary for us)
            npe5__Affiliation__c aff = new npe5__Affiliation__c(
                npe5__Contact__c     = ctId,
                npe5__Organization__c= orgId,
                npe5__Status__c      = 'Current',
                npe5__Primary__c     = true,
                npe5__StartDate__c   = today
            );
            newAffiliations.add(aff);

            // Ensure the Contact lookup is correct even if NPSP automation
            // is misconfigured or a flow was deactivated.
            contactsToUpdate.add(new Contact(
                Id                               = ctId,
                npsp__Primary_Affiliation__c     = orgId
            ));
        }

        // ── DML 1 – insert new affiliations ─────────────────────────────────
        // NPSP's Affiliation automation fires here:
        //   • prior primary affiliation → Former, Primary=false, EndDate=today
        //   • may also refresh Contact.npsp__Primary_Affiliation__c
        if (!newAffiliations.isEmpty()) {
            insert newAffiliations;
        }

        // ── DML 2 – guarantee Contact lookup points to the Organization ─────
        if (!contactsToUpdate.isEmpty()) {
            update contactsToUpdate;
        }
    }
}
