public class RecurringGiftService {

    public class RecurringGiftException extends Exception {}

    public class GiftRequest {
        public Id contactId;
        public Decimal amount;
        public Integer dayOfMonth;    // 1-31
        public Date startDate;
        public Integer installments;  // null or 0 = no end date
        public String paymentMethod;  // 'Credit Card', 'ACH' or 'Check'
    }

    public static List<Id> createMonthlyGifts(List<GiftRequest> requests) {
        // Return empty list for null or empty input
        if (requests == null || requests.isEmpty()) {
            return new List<Id>();
        }

        // Validate ALL requests before any DML
        for (GiftRequest req : requests) {
            if (req == null) {
                throw new RecurringGiftException('Gift request cannot be null.');
            }
            if (req.contactId == null) {
                throw new RecurringGiftException('Contact Id is required for each gift request.');
            }
            if (req.amount == null || req.amount <= 0) {
                throw new RecurringGiftException('Amount must be greater than zero.');
            }
            if (req.dayOfMonth == null || req.dayOfMonth < 1 || req.dayOfMonth > 31) {
                throw new RecurringGiftException('Day of month must be between 1 and 31.');
            }
            if (req.startDate == null) {
                throw new RecurringGiftException('Start date is required for each gift request.');
            }
        }

        // Build Recurring Donation records
        List<npe03__Recurring_Donation__c> donations = new List<npe03__Recurring_Donation__c>();

        for (GiftRequest req : requests) {
            npe03__Recurring_Donation__c rd = new npe03__Recurring_Donation__c();

            // Donor
            rd.npe03__Contact__c = req.contactId;

            // Amount per installment
            rd.npe03__Amount__c = req.amount;

            // Monthly schedule
            rd.npe03__Installment_Period__c = 'Monthly';
            rd.npsp__InstallmentFrequency__c = 1;
            rd.npsp__StartDate__c = req.startDate;

            // Day-of-month handling (day 31 maps to Enhanced RD last-day-of-month flag)
            if (req.dayOfMonth == 31) {
                rd.npsp__Always_Use_Last_Day_Of_Month__c = true;
                rd.npsp__Day_of_Month__c = 31;
            } else {
                rd.npsp__Always_Use_Last_Day_Of_Month__c = false;
                rd.npsp__Day_of_Month__c = req.dayOfMonth;
            }

            // Installments: open-ended vs fixed-length
            if (req.installments != null && req.installments > 0) {
                rd.npe03__Installments__c = req.installments;
                rd.npe03__Open_Ended_Status__c = 'None';
            } else {
                rd.npe03__Installments__c = null;
                rd.npe03__Open_Ended_Status__c = 'Never';
            }

            // Status and payment method
            rd.npsp__Status__c = 'Active';
            rd.npsp__PaymentMethod__c = req.paymentMethod;

            // Enhanced RD type
            rd.npsp__RecurringType__c = 'Single Installment';

            // Date the agreement was established
            rd.npe03__Date_Established__c = req.startDate;

            donations.add(rd);
        }

        // Single DML statement
        insert donations;

        // Return new Ids in request order
        List<Id> newIds = new List<Id>(donations.size());
        for (npe03__Recurring_Donation__c rd : donations) {
            newIds.add(rd.Id);
        }
        return newIds;
    }
}
