public class GauAllocationService {

    public class AllocationException extends Exception {}

    public static List<npsp__Allocation__c> allocateByPercent(
        Id opportunityId,
        Map<Id, Decimal> percentByGauId
    ) {
        // --- Validate inputs before any DML ---

        if (percentByGauId == null || percentByGauId.isEmpty()) {
            throw new AllocationException('percentByGauId must not be null or empty.');
        }

        Decimal totalPercent = 0;
        for (Decimal pct : percentByGauId.values()) {
            if (pct == null || pct <= 0) {
                throw new AllocationException('Each percentage must be greater than zero.');
            }
            totalPercent += pct;
        }

        if (totalPercent > 100) {
            throw new AllocationException(
                'Percentages sum to ' + totalPercent + '; maximum allowed is 100.'
            );
        }

        // Validate all referenced GAUs exist and are active
        Set<Id> gauIds = percentByGauId.keySet();
        Map<Id, npsp__General_Accounting_Unit__c> gauMap = new Map<Id, npsp__General_Accounting_Unit__c>(
            [
                SELECT Id, Name, npsp__Active__c
                FROM npsp__General_Accounting_Unit__c
                WHERE Id IN :gauIds
            ]
        );

        for (Id gauId : gauIds) {
            npsp__General_Accounting_Unit__c gau = gauMap.get(gauId);
            if (gau == null) {
                throw new AllocationException('General Accounting Unit not found: ' + gauId);
            }
            if (!gau.npsp__Active__c) {
                throw new AllocationException('General Accounting Unit is inactive: ' + gau.Name);
            }
        }

        // --- Replace existing allocations (delete first, then insert) ---

        delete [
            SELECT Id
            FROM npsp__Allocation__c
            WHERE npsp__Opportunity__c = :opportunityId
        ];

        List<npsp__Allocation__c> newAllocations = new List<npsp__Allocation__c>();
        for (Id gauId : percentByGauId.keySet()) {
            npsp__Allocation__c alloc = new npsp__Allocation__c();
            alloc.npsp__Opportunity__c = opportunityId;
            alloc.npsp__General_Accounting_Unit__c = gauId;
            alloc.npsp__Percent__c = percentByGauId.get(gauId);
            // Intentionally leave npsp__Amount__c null so NPSP recalculates the dollar
            // amount dynamically whenever the Opportunity amount changes.
            newAllocations.add(alloc);
        }

        insert newAllocations;

        return newAllocations;
    }
}
