 * `TA_Contact_CreateWelcomeTask` after-insert action while allowing all other
 * registered actions (e.g. `TA_Contact_FormatPhone`) to execute normally.
 *
 * The bypass is scoped to the DML call and is always cleared before the method
 * returns, so any contacts inserted later in the same transaction will still
 * receive their welcome tasks.
 */
public with sharing class ContactImportService {

    private static final String WELCOME_TASK_ACTION = 'TA_Contact_CreateWelcomeTask';

    /**
     * Inserts the supplied contacts in a single DML statement.
     * Only `TA_Contact_CreateWelcomeTask` is bypassed; all other Contact
     * automation (including phone formatting) runs as normal.
     *
     * @param contacts  Contacts to insert; no-op when null or empty.
     */
    public static void importContacts(List<Contact> contacts) {
        if (contacts == null || contacts.isEmpty()) {
            return;
        }

        // Bypass only the welcome-task action so the before-insert phone
        // formatting action still fires.
        MetadataTriggerHandler.bypass(WELCOME_TASK_ACTION);
        try {
            insert contacts;
        } finally {
            // Always clear the bypass so subsequent DML in this transaction
            // (or in a caller's context) proceeds with full automation.
            MetadataTriggerHandler.clearBypass(WELCOME_TASK_ACTION);
        }
    }
}
