/**
 * DML-less / SOQL-less tests for TA_Opportunity_GuardAmountDecrease.
 * Records are built entirely in memory using TriggerTestUtility.getFakeId;
 * beforeUpdate is invoked directly on the action instance.
 */
@IsTest
private class TA_Opportunity_GuardAmountDecreaseTest {

    /**
     * Behaviour 1: A reduction of MORE than half (1000 → 499) must be rejected
     * with exactly one error carrying ERROR_MESSAGE.
     */
    @IsTest
    static void amountReducedByMoreThanHalf_isRejected() {
        Id fakeId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);

        List<Opportunity> triggerOld = new List<Opportunity>{
            new Opportunity(Id = fakeId, Amount = 1000)
        };
        List<Opportunity> triggerNew = new List<Opportunity>{
            new Opportunity(Id = fakeId, Amount = 499)
        };

        new TA_Opportunity_GuardAmountDecrease().beforeUpdate(triggerNew, triggerOld);

        System.assert(triggerNew[0].hasErrors(), 'Record should carry an error');
        List<SObjectError> errors = triggerNew[0].getErrors();
        System.assertEquals(1, errors.size(), 'Exactly one error expected');
        System.assertEquals(
            TA_Opportunity_GuardAmountDecrease.ERROR_MESSAGE,
            errors[0].getMessage(),
            'Error message mismatch'
        );
    }

    /**
     * Behaviour 2: A reduction of EXACTLY half (1000 → 500) is accepted (no error).
     * Behaviour 3: An increase (1000 → 1500) is accepted.
     * Behaviour 4: A record whose previous Amount was null is accepted without exception.
     * Grouped because they are all "happy-path / boundary" cases.
     */
    @IsTest
    static void acceptedScenarios_produceNoErrors() {
        // --- exactly half ---
        Id idHalf = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        List<Opportunity> oldHalf = new List<Opportunity>{
            new Opportunity(Id = idHalf, Amount = 1000)
        };
        List<Opportunity> newHalf = new List<Opportunity>{
            new Opportunity(Id = idHalf, Amount = 500)
        };
        new TA_Opportunity_GuardAmountDecrease().beforeUpdate(newHalf, oldHalf);
        System.assert(
            !newHalf[0].hasErrors(),
            'Exactly-half decrease should NOT produce an error'
        );

        // --- increase ---
        Id idInc = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        List<Opportunity> oldInc = new List<Opportunity>{
            new Opportunity(Id = idInc, Amount = 1000)
        };
        List<Opportunity> newInc = new List<Opportunity>{
            new Opportunity(Id = idInc, Amount = 1500)
        };
        new TA_Opportunity_GuardAmountDecrease().beforeUpdate(newInc, oldInc);
        System.assert(
            !newInc[0].hasErrors(),
            'Increase should NOT produce an error'
        );

        // --- previous Amount was null ---
        Id idNull = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        List<Opportunity> oldNull = new List<Opportunity>{
            new Opportunity(Id = idNull, Amount = (Decimal) null)
        };
        List<Opportunity> newNull = new List<Opportunity>{
            new Opportunity(Id = idNull, Amount = 500)
        };
        // Must not throw; also no error expected.
        new TA_Opportunity_GuardAmountDecrease().beforeUpdate(newNull, oldNull);
        System.assert(
            !newNull[0].hasErrors(),
            'Null previous Amount should NOT produce an error'
        );
    }

    /**
     * Behaviour 5: One call with several records where only some break the rule.
     * Exactly the violating records get the error; the others carry none.
     */
    @IsTest
    static void multipleRecords_onlyViolatingOnesGetErrors() {
        Id idViolate1 = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Id idOk1      = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Id idOk2      = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Id idViolate2 = TriggerTestUtility.getFakeId(Opportunity.SObjectType);

        List<Opportunity> triggerOld = new List<Opportunity>{
            new Opportunity(Id = idViolate1, Amount = 1000),
            new Opportunity(Id = idOk1,      Amount = 1000),
            new Opportunity(Id = idOk2,      Amount = 800),
            new Opportunity(Id = idViolate2, Amount = 200)
        };
        List<Opportunity> triggerNew = new List<Opportunity>{
            new Opportunity(Id = idViolate1, Amount = 400),   // 400 < 500 → error
            new Opportunity(Id = idOk1,      Amount = 500),   // exactly half → ok
            new Opportunity(Id = idOk2,      Amount = 1200),  // increase → ok
            new Opportunity(Id = idViolate2, Amount = 99)     // 99 < 100 → error
        };

        new TA_Opportunity_GuardAmountDecrease().beforeUpdate(triggerNew, triggerOld);

        // Violating records carry exactly one ERROR_MESSAGE each
        System.assert(triggerNew[0].hasErrors(), 'Record 0 (violate1) should have errors');
        System.assertEquals(1, triggerNew[0].getErrors().size());
        System.assertEquals(
            TA_Opportunity_GuardAmountDecrease.ERROR_MESSAGE,
            triggerNew[0].getErrors()[0].getMessage()
        );

        System.assert(triggerNew[3].hasErrors(), 'Record 3 (violate2) should have errors');
        System.assertEquals(1, triggerNew[3].getErrors().size());
        System.assertEquals(
            TA_Opportunity_GuardAmountDecrease.ERROR_MESSAGE,
            triggerNew[3].getErrors()[0].getMessage()
        );

        // Non-violating records carry no errors
        System.assert(!triggerNew[1].hasErrors(), 'Record 1 (ok) should have NO errors');
        System.assert(!triggerNew[2].hasErrors(), 'Record 2 (ok) should have NO errors');
    }
}
