public with sharing class TA_Contact_PreventDuplicateEmail
        implements TriggerAction.BeforeInsert, TriggerAction.BeforeUpdate {

    private static final String DUPLICATE_EMAIL_ERROR =
            'Another contact on this account already uses this email address.';

    public void beforeInsert(List<SObject> triggerNew) {
        processContacts((List<Contact>) triggerNew, null);
    }

    public void beforeUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        processContacts((List<Contact>) triggerNew, (List<Contact>) triggerOld);
    }

    private void processContacts(List<Contact> newContacts, List<Contact> oldContacts) {
        // Identify records that need the duplicate check
        List<Contact> toCheck = new List<Contact>();
        Set<Id> accountIds = new Set<Id>();
        Set<String> emails = new Set<String>();

        Map<Id, Contact> oldMap = null;
        if (oldContacts != null) {
            oldMap = new Map<Id, Contact>(oldContacts);
        }

        for (Contact c : newContacts) {
            // Contacts without an Account or without an Email are not checked
            if (c.AccountId == null || String.isBlank(c.Email)) {
                continue;
            }

            // On update, only check records whose Email or AccountId changed
            if (oldContacts != null) {
                Contact oldC = oldMap.get(c.Id);
                if (oldC != null) {
                    Boolean emailChanged = oldC.Email != c.Email;
                    Boolean accountChanged = oldC.AccountId != c.AccountId;
                    if (!emailChanged && !accountChanged) {
                        continue;
                    }
                }
            }

            toCheck.add(c);
            accountIds.add(c.AccountId);
            emails.add(c.Email);
        }

        if (accountIds.isEmpty() || emails.isEmpty()) {
            return;
        }

        // Single SOQL: find existing contacts that share both the account and an email we care about
        Map<String, Set<Id>> dbKeyToIds = new Map<String, Set<Id>>();
        for (Contact existing : [
                SELECT Id, Email, AccountId
                FROM Contact
                WHERE AccountId IN :accountIds
                  AND Email IN :emails
        ]) {
            String key = existing.AccountId + '|' + existing.Email.toLowerCase();
            Set<Id> ids = dbKeyToIds.get(key);
            if (ids == null) {
                ids = new Set<Id>();
                dbKeyToIds.put(key, ids);
            }
            ids.add(existing.Id);
        }

        // Batch-level tracking so the first record for a given account+email wins
        Set<String> batchTaken = new Set<String>();

        for (Contact c : toCheck) {
            String key = c.AccountId + '|' + c.Email.toLowerCase();
            Boolean conflict = false;

            // Check against existing (committed) contacts in the database
            Set<Id> dbIds = dbKeyToIds.get(key);
            if (dbIds != null) {
                if (oldContacts == null) {
                    // Insert: the new contact does not exist yet, so any match is a real conflict
                    conflict = true;
                } else {
                    // Update: a contact never conflicts with itself
                    Set<Id> others = new Set<Id>(dbIds);
                    others.remove(c.Id);
                    if (!others.isEmpty()) {
                        conflict = true;
                    }
                }
            }

            // Check against earlier records in the same save (first-come-first-served)
            if (!conflict && batchTaken.contains(key)) {
                conflict = true;
            }

            if (conflict) {
                c.addError(DUPLICATE_EMAIL_ERROR);
            } else {
                batchTaken.add(key);
            }
        }
    }
}
