public class TA_Case_PreventReopen implements TriggerAction.BeforeUpdate {
    public void beforeUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        if (triggerNew == null || triggerNew.isEmpty()) {
            return;
        }

        Map<Id, Case> oldMap = new Map<Id, Case>();

        if (triggerOld != null) {
            for (SObject oldRec : triggerOld) {
                if (oldRec instanceof Case) {
                    Case oldCase = (Case) oldRec;
                    if (oldCase.Id != null) {
                        oldMap.put(oldCase.Id, oldCase);
                    }
                }
            }
        }

        for (SObject rec : triggerNew) {
            if (rec instanceof Case) {
                Case c = (Case) rec;
                Case oldCase = oldMap.get(c.Id);

                if (oldCase != null && oldCase.Status == 'Closed' && c.Status != 'Closed') {
                    c.addError('Closed cases cannot be reopened. Please create a new case.');
                }
            }
        }
    }
}
