public class TA_Case_AddClosureComment implements TriggerAction.AfterUpdate {
    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        if (triggerNew == null || triggerNew.isEmpty()) {
            return;
        }

        Map<Id, Case> oldMap = new Map<Id, Case>();

        if (triggerOld != null) {
            for (SObject oldRec : triggerOld) {
                if (oldRec instanceof Case) {
                    Case oldCase = (Case) oldRec;
                    if (oldCase.Id != null) {
                        oldMap.put(oldCase.Id, oldCase);
                    }
                }
            }
        }

        List<CaseComment> comments = new List<CaseComment>();

        for (SObject rec : triggerNew) {
            if (rec instanceof Case) {
                Case c = (Case) rec;
                Case oldCase = oldMap.get(c.Id);

                if (oldCase != null && c.Id != null && c.Status == 'Closed' && oldCase.Status != 'Closed') {
                    comments.add(
                        new CaseComment(
                            ParentId = c.Id,
                            CommentBody = 'Case closed on ' + String.valueOf(Date.today()),
                            IsPublished = false
                        )
                    );
                }
            }
        }

        if (!comments.isEmpty()) {
            insert comments;
        }
    }
}
