public with sharing class TA_Opportunity_LogAmountChange implements TriggerAction.AfterUpdate {
    private static final String AUDIT_TASK_SUBJECT = 'Amount changed';
    private static final String AUDIT_TASK_STATUS = 'Completed';

    // Transaction-scoped guard so an Opportunity can have at most one Amount-changed task
    // per Apex transaction, including recursive updates caused by other actions such as rounding.
    private static Set<Id> loggedAmountChangeIds = new Set<Id>();

    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        Map<Id, SObject> oldById = new Map<Id, SObject>(triggerOld);
        List<Task> auditTasks = new List<Task>();
        Set<Id> loggingThisRun = new Set<Id>();

        for (SObject newSobject : triggerNew) {
            Id opportunityId = newSobject.Id;

            if (opportunityId == null || loggedAmountChangeIds.contains(opportunityId)) {
                continue;
            }

            SObject oldSobject = oldById.get(opportunityId);

            // After-update actions should only evaluate records that existed before this update.
            if (oldSobject == null) {
                continue;
            }

            Opportunity newOpportunity = (Opportunity) newSobject;
            Opportunity oldOpportunity = (Opportunity) oldSobject;

            if (oldOpportunity.Amount != newOpportunity.Amount) {
                auditTasks.add(new Task(
                    Subject = AUDIT_TASK_SUBJECT,
                    WhatId = opportunityId,
                    Status = AUDIT_TASK_STATUS
                ));

                loggingThisRun.add(opportunityId);
            }
        }

        if (!auditTasks.isEmpty()) {
            insert auditTasks;
            loggedAmountChangeIds.addAll(loggingThisRun);
        }
    }
}
